: () => $('Proses Tiket'), "Catat Gagal (Tiket)": () => $('Catat Gagal (Tiket)'), "Tulis Log Error (Tiket)": () => $('Tulis Log Error (Tiket)'), "Kirim Respons Gagal (Tiket)": () => $('Kirim Respons Gagal (Tiket)'), "Tulis Tiket?": () => $('Tulis Tiket?'), "Tulis Tiket": () => $('Tulis Tiket'), "Kirim Hasil Tiket": () => $('Kirim Hasil Tiket'), "Kirim Penolakan Tiket": () => $('Kirim Penolakan Tiket') };
const __asli = (n) => (n in __nyata ? __nyata[n]() : $(n));
const __peta = {"Siapkan Log Error (Pendaftaran)": "Catat Gagal (Pendaftaran)", "Data Log (Pendaftaran)": "Catat Gagal (Pendaftaran)", "Susun Baris Log (Pendaftaran)": "Catat Gagal (Pendaftaran)", "Validasi Peserta": "Proses Peserta", "Olah Sheet Peserta": "Proses Peserta", "Proses Peserta": "Proses Peserta", "Siapkan Log Error (Peserta)": "Catat Gagal (Peserta)", "Data Log (Peserta)": "Catat Gagal (Peserta)", "Susun Baris Log (Peserta)": "Catat Gagal (Peserta)", "Validasi Kirim": "Proses Kirim Draf", "Olah Sheet Kirim": "Proses Kirim Draf", "Proses Kirim": "Proses Kirim Draf", "Siapkan Log Error (Kirim Draf)": "Catat Gagal (Kirim Draf)", "Data Log (Kirim Draf)": "Catat Gagal (Kirim Draf)", "Susun Baris Log (Kirim Draf)": "Catat Gagal (Kirim Draf)", "Validasi Tiket": "Proses Tiket", "Olah Sheet Tiket": "Proses Tiket", "Proses Tiket": "Proses Tiket", "Siapkan Log Error (Tiket)": "Catat Gagal (Tiket)", "Data Log (Tiket)": "Catat Gagal (Tiket)", "Susun Baris Log (Tiket)": "Catat Gagal (Tiket)"};
const __lokal = ["Validasi Pendaftaran", "Olah Sheet Pendaftaran", "Cocokkan Prospek"];
const __hasil = {};
const __tidakJalan = (n) => ({ isExecuted: false, first: () => { throw new Error('Langkah ' + n + ' tidak dijalankan.'); }, all: () => [] });
function __ref(n) {
  if (n in __hasil) return { isExecuted: true, first: () => __hasil[n][0], all: () => __hasil[n] };
  if (__lokal.includes(n)) return __tidakJalan(n);
  if (n in __peta) {
    const nyata = __asli(__peta[n]);
    if (!nyata.isExecuted) return __tidakJalan(n);
    const j = (nyata.first().json.__langkah || {})[n];
    if (j === undefined) return __tidakJalan(n);
    return { isExecuted: true, first: () => ({ json: j }), all: () => [{ json: j }] };
  }
  return __asli(n);
}
const __masuk = (items) => ({ first: () => items[0], all: () => items });
function __jalan(nama, fn, items) {
  try {
    const out = fn(__ref, __masuk(items));
    __hasil[nama] = out;
    return out;
  } catch (e) {
    e.message = '[' + nama + '] ' + e.message;
    throw e;
  }
}
const __selesai = (json) => [{
