const AKTOR = { staf: 'Staf', ae_a: 'AE A', ae_b: 'AE B', admin: 'Admin' };
const STATUS_PIPELINE = ['Baru', 'Kualifikasi', 'Follow-up', 'Penawaran draf'];
const STATUS_DRAF = ['Menunggu persetujuan', 'Disetujui', 'Ditolak', 'Siap kirim (simulasi)', 'Terkirim (simulasi)'];

// E1: arsip = aktif FALSE; baris tanpa nilai aktif (data sebelum E1) dianggap aktif.
function pesertaAktif(p) {
  return String((p && p.aktif) ?? '').trim().toUpperCase() !== 'FALSE';
}

function nomorBerikut(baris, kolom) {
  return Math.max(0, ...baris.map((r) => parseInt(String(r[kolom] || '').replace(/\D/g, ''), 10) || 0)) + 1;
}

function idBaru(awalan, nomor) {
  return awalan + String(nomor).padStart(4, '0');
}

function sel(v) {
  return typeof v === 'boolean'
    ? { userEnteredValue: { boolValue: v } }
    : { userEnteredValue: { stringValue: v == null ? '' : String(v) } };
}

// Menambah baris di akhir sheet; kolom mengikuti urutan header sheet itu sendiri.
function tambahBaris(D, sheet, daftar) {
  const kolom = D.header[sheet];
  if (!kolom) throw new Error(`Sheet ${sheet} tidak dibaca.`);
  for (const b of daftar) {
    const asing = Object.keys(b).filter((k) => !kolom.includes(k));
    if (asing.length) throw new Error(`Kolom ${asing.join(', ')} tidak ada di header sheet ${sheet}.`);
  }
  return {
    appendCells: {
      sheetId: D.gid[sheet],
      rows: daftar.map((b) => ({ values: kolom.map((k) => sel(b[k])) })),
      fields: 'userEnteredValue',
    },
  };
}

// Mengubah sel tertentu pada baris yang sudah ada (objek dari tabel, membawa _baris).
function ubahSel(D, sheet, objek, perubahan) {
  if (!objek || !objek._baris || objek._baris < 2) throw new Error(`Baris ${sheet} tidak valid untuk diubah.`);
  return Object.entries(perubahan).map(([k, v]) => {
    const c = D.header[sheet].indexOf(k);
    if (c < 0) throw new Error(`Kolom ${k} tidak ada di header sheet ${sheet}.`);
    return {
      updateCells: {
        range: {
          sheetId: D.gid[sheet],
          startRowIndex: objek._baris - 1,
          endRowIndex: objek._baris,
          startColumnIndex: c,
          endColumnIndex: c + 1,
        },
        rows: [{ values: [sel(v)] }],
        fields: 'userEnteredValue',
      },
    };
  });
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { AKTOR, STATUS_PIPELINE, STATUS_DRAF, pesertaAktif, nomorBerikut, idBaru, sel, tambahBaris, ubahSel };
}

// SIMULASI MSI — Aturan formulir pendaftaran Ekstensi E1 (E-01, POST /pendaftaran di WF-06).
// Fungsi murni; diuji di aturan_pendaftaran.test.js. Baris module.exports hanya untuk uji unit.
// Saat dirakit, normalisasi_kunci.js dan sheet_tulis.js ditempel di atas file ini
// (normalisasiKunci, normalisasiIdProspek, nomorBerikut, idBaru, tambahBaris).

const KATEGORI_E1 = ['CSR', 'Tata Kelola (GRC)', 'Human Capital', 'Digital', 'BUMD'];
// Hanya pola dummy 0812-0000-xxxx (CLAUDE.md, Ekstensi E1): nomor sungguhan tidak pernah diterima.
const POLA_HP_DUMMY = /^08120000(\d{4})$/;
const AKTOR_FORMULIR = 'Formulir';

function teksRapi(v) {
  return String(v ?? '').replace(/\s+/g, ' ').trim();
}

// "0812-0000-0011", "0812 0000 0011", "081200000011" -> "0812-0000-0011"; selain pola dummy -> null.
function normalisasiHpDummy(v) {
  const m = String(v ?? '').replace(/[\s-]/g, '').match(POLA_HP_DUMMY);
  return m ? `0812-0000-${m[1]}` : null;
}

function validasiPendaftaran(body) {
  const b = body || {};
  const data = {
    id_permintaan: teksRapi(b.id_permintaan),
    nama_perusahaan: teksRapi(b.nama_perusahaan),
    sektor: teksRapi(b.sektor),
    nama_pic: teksRapi(b.nama_pic),
    no_hp_pic: normalisasiHpDummy(b.no_hp_pic),
    kategori: teksRapi(b.kategori),
    pertanyaan: String(b.pertanyaan ?? '').trim(),
    setuju_simulasi: b.setuju_simulasi === true || b.setuju_simulasi === 'true',
  };

  const pesan = [];
  if (!data.id_permintaan) pesan.push('id_permintaan wajib diisi.');
  if (!data.nama_perusahaan) pesan.push('Nama perusahaan wajib diisi.');
  else if (normalisasiIdProspek(data.nama_perusahaan)) pesan.push('Isi nama perusahaan, bukan ID prospek.');
  else if (!normalisasiKunci(data.nama_perusahaan)) pesan.push('Nama perusahaan tidak valid.');
  else if (data.nama_perusahaan.length > 100) pesan.push('Nama perusahaan maksimal 100 karakter.');
  if (!data.sektor) pesan.push('Sektor wajib diisi.');
  else if (data.sektor.length > 60) pesan.push('Sektor maksimal 60 karakter.');
  if (!data.nama_pic) pesan.push('Nama PIC wajib diisi.');
  else if (data.nama_pic.length > 80) pesan.push('Nama PIC maksimal 80 karakter.');
  if (!data.no_hp_pic) pesan.push('Nomor HP PIC tidak valid. Gunakan format 0812-0000-xxxx.');
  if (!KATEGORI_E1.includes(data.kategori)) pesan.push(`Kategori tidak valid. Pilih salah satu: ${KATEGORI_E1.join(', ')}.`);
  if (data.pertanyaan.length > 500) pesan.push('Pertanyaan awal maksimal 500 karakter.');
  if (!data.setuju_simulasi) pesan.push('Centang persetujuan ketentuan pendaftaran untuk melanjutkan.');

  return { valid: pesan.length === 0, pesan: pesan.join(' '), ...data };
}

function tandaPermintaan(idPermintaan) {
  return `id_permintaan=${idPermintaan}`;
}

// Histori milik pendaftaran ini (idempotensi): aktor Formulir dan catatan diakhiri tanda id_permintaan.
function cariHistoriPendaftaran(histori, idPermintaan) {
  const tanda = '; ' + tandaPermintaan(idPermintaan);
  return histori.find(
    (r) =>
      String(r.aktor).trim() === AKTOR_FORMULIR &&
      ['pendaftaran', 'duplikat_terdeteksi'].includes(String(r.jenis).trim()) &&
      String(r.catatan || '').endsWith(tanda)
  );
}

function susunRespons(baru, p, berulang) {
  const nama = p.nama_perusahaan;
  let pesan = baru
    ? `Pendaftaran ${nama} tercatat sebagai ${p.id_prospek}.`
    : `${nama} sudah terdaftar sebagai ${p.id_prospek}; data tidak ditambah.`;
  if (!baru && String(p.aktif).trim().toUpperCase() === 'FALSE') pesan += ' Data ini sedang diarsipkan; hubungi admin.';
  return { status: 'ok', baru, id_prospek: p.id_prospek, nama_perusahaan: nama, pesan, berulang, dilengkapi: [] };
}

function susunTeruskan(m, idProspek) {
  // Pertanyaan awal diteruskan ke WF-01 (POST /chat) dengan id_permintaan turunan, sehingga coba ulang
  // pendaftaran tidak menggandakan Percakapan (WF-01 idempoten per id_permintaan).
  return m.pertanyaan
    ? { perlu_chat: true, body_chat: { id_permintaan: `${m.id_permintaan}-awal`, prospek: idProspek, pertanyaan: m.pertanyaan } }
    : { perlu_chat: false, body_chat: null };
}

// D = keluaran Olah Data Sheet ({tabel, header, gid}) untuk Prospek dan Histori; m = hasil validasiPendaftaran.
// Hasil: aksi 'lama' (permintaan berulang, tidak menulis) atau 'tulis' (satu batchUpdate atomik).
function prosesPendaftaran(D, m, waktu) {
  const daftar = D.tabel.Prospek.filter((r) => String(r.id_prospek || '').trim() !== '');
  const tanda = tandaPermintaan(m.id_permintaan);

  const lama = cariHistoriPendaftaran(D.tabel.Histori, m.id_permintaan);
  if (lama) {
    const p = daftar.find((r) => String(r.id_prospek).trim() === String(lama.id_prospek).trim()) || {
      id_prospek: lama.id_prospek,
      nama_perusahaan: m.nama_perusahaan,
    };
    return { aksi: 'lama', respons: susunRespons(lama.jenis === 'pendaftaran', p, true), teruskan: susunTeruskan(m, p.id_prospek) };
  }

  const kunci = normalisasiKunci(m.nama_perusahaan);
  const idHistori = idBaru('H', nomorBerikut(D.tabel.Histori, 'id_histori'));
  const ada = daftar.find((r) => String(r.kunci_normal || '').trim() === kunci);

  // FR-08 langkah 3: perusahaan sudah ada -> tidak menambah baris; Histori duplikat_terdeteksi.
  // R1: prospek yang tercatat lebih dulu dari chat belum punya data PIC. Kolom yang MASIH KOSONG dilengkapi
  // dari formulir (tidak pernah menimpa isi yang ada), satu Histori ubah_peserta per kolom; prospek arsip tidak diubah.
  if (ada) {
    const isian = { sektor: m.sektor, nama_pic: m.nama_pic, no_hp_pic: m.no_hp_pic, kategori: m.kategori };
    const lengkapi = pesertaAktif(ada)
      ? Object.entries(isian).filter(([k, v]) => v && String(ada[k] ?? '').trim() === '' && (D.header.Prospek || []).includes(k))
      : [];
    let nomor = nomorBerikut(D.tabel.Histori, 'id_histori');
    const historiLengkapi = lengkapi.map(([k, v]) => ({
      id_histori: idBaru('H', nomor++),
      waktu,
      id_prospek: ada.id_prospek,
      aktor: AKTOR_FORMULIR,
      jenis: 'ubah_peserta',
      nilai_lama: '',
      nilai_baru: v,
      catatan: `Kolom ${k} dilengkapi dari formulir pendaftaran`,
    }));
    const histori = {
      id_histori: idBaru('H', nomor++),
      waktu,
      id_prospek: ada.id_prospek,
      aktor: AKTOR_FORMULIR,
      jenis: 'duplikat_terdeteksi',
      nilai_lama: '',
      nilai_baru: '',
      catatan: `Pendaftaran untuk perusahaan yang sudah terdaftar; nama masuk: "${m.nama_perusahaan}"; ${tanda}`,
    };
    const requests = lengkapi.length
      ? [...ubahSel(D, 'Prospek', ada, { ...Object.fromEntries(lengkapi), diubah: waktu }), tambahBaris(D, 'Histori', [...historiLengkapi, histori])]
      : [tambahBaris(D, 'Histori', [histori])];
    const respons = susunRespons(false, ada, false);
    respons.dilengkapi = lengkapi.map(([k]) => k);
    if (lengkapi.length) respons.pesan = `${ada.nama_perusahaan} sudah terdaftar sebagai ${ada.id_prospek}. Data yang masih kosong telah dilengkapi.`;
    return {
      aksi: 'tulis',
      body_tulis: { requests },
      respons,
      teruskan: susunTeruskan(m, ada.id_prospek),
    };
  }

  // FR-08 langkah 4: ID berikutnya (P11, P12, ...); AE dengan prospek paling sedikit (seri: AE A), sama dengan WF-01.
  const nomorMaks = Math.max(0, ...daftar.map((r) => parseInt(String(r.id_prospek).replace(/\D/g, ''), 10) || 0));
  const jumlah = { 'AE A': 0, 'AE B': 0 };
  for (const r of daftar) if (r.ae in jumlah) jumlah[r.ae] += 1;

  const p = {
    id_prospek: 'P' + String(nomorMaks + 1).padStart(2, '0'),
    nama_perusahaan: m.nama_perusahaan,
    kunci_normal: kunci,
    sektor: m.sektor,
    ae: jumlah['AE B'] < jumlah['AE A'] ? 'AE B' : 'AE A',
    status: 'Baru',
    kebutuhan: '',
    status_kebutuhan: 'Belum terkonfirmasi', // FR-10
    tgl_tindak_lanjut: '',
    pengingat: '',
    dibuat: waktu,
    diubah: waktu,
    nama_pic: m.nama_pic,
    no_hp_pic: m.no_hp_pic,
    kategori: m.kategori,
    sumber: 'formulir',
    aktif: 'TRUE',
  };
  const histori = {
    id_histori: idHistori,
    waktu,
    id_prospek: p.id_prospek,
    aktor: AKTOR_FORMULIR,
    jenis: 'pendaftaran',
    nilai_lama: '',
    nilai_baru: p.nama_perusahaan,
    catatan: `Pendaftaran baru dari formulir; kategori ${m.kategori}; ${tanda}`,
  };
  return {
    aksi: 'tulis',
    body_tulis: { requests: [tambahBaris(D, 'Prospek', [p]), tambahBaris(D, 'Histori', [histori])] },
    respons: susunRespons(true, p, false),
    teruskan: susunTeruskan(m, p.id_prospek),
  };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { KATEGORI_E1, teksRapi, tandaPermintaan, normalisasiHpDummy, validasiPendaftaran, cariHistoriPendaftaran, prosesPendaftaran };
}

// SIMULASI MSI — Aturan tabel peserta dan Kirim (simulasi) Ekstensi E1 (E-02 POST /peserta, E-03 POST /draf/kirim).
// Fungsi murni; diuji di aturan_peserta.test.js. Baris module.exports hanya untuk uji unit.
// Saat dirakit, normalisasi_kunci.js, sheet_tulis.js, dan aturan_pendaftaran.js ditempel di atas file ini.
// Arsip = aktif FALSE; baris Prospek dan Histori tidak pernah dihapus. Tidak ada pengiriman nyata (S-05).

const AKSI_PESERTA = ['tambah', 'ubah', 'arsip'];
const KOLOM_UBAH_PESERTA = ['nama_perusahaan', 'sektor', 'nama_pic', 'no_hp_pic', 'kategori', 'ae'];
const DAFTAR_AE = ['AE A', 'AE B'];

// Memeriksa satu kolom isian peserta; mengembalikan [nilai rapi, pesan galat atau ''].
function periksaKolomPeserta(k, v, oleh) {
  if (k === 'no_hp_pic') {
    const hp = normalisasiHpDummy(v);
    return [hp, hp ? '' : 'Nomor HP PIC tidak valid. Gunakan format 0812-0000-xxxx.'];
  }
  const s = teksRapi(v);
  if (k === 'nama_perusahaan') {
    if (!s) return [s, 'Nama perusahaan wajib diisi.'];
    if (normalisasiIdProspek(s)) return [s, 'Isi nama perusahaan, bukan ID prospek.'];
    if (!normalisasiKunci(s)) return [s, 'Nama perusahaan tidak valid.'];
    return [s, s.length > 100 ? 'Nama perusahaan maksimal 100 karakter.' : ''];
  }
  if (k === 'sektor') return [s, !s ? 'Sektor wajib diisi.' : s.length > 60 ? 'Sektor maksimal 60 karakter.' : ''];
  if (k === 'nama_pic') return [s, !s ? 'Nama PIC wajib diisi.' : s.length > 80 ? 'Nama PIC maksimal 80 karakter.' : ''];
  if (k === 'kategori') return [s, KATEGORI_E1.includes(s) ? '' : `Kategori tidak valid. Pilih salah satu: ${KATEGORI_E1.join(', ')}.`];
  if (k === 'ae') {
    if (oleh !== 'admin') return [s, 'Hanya admin yang boleh menentukan AE.'];
    return [s, DAFTAR_AE.includes(s) ? '' : 'AE harus AE A atau AE B.'];
  }
  return [s, `Kolom ${k} tidak bisa diubah.`];
}

// body: aksi, oleh, id_prospek (ubah/arsip), id_permintaan (tambah), kolom isian, catatan (opsional).
function validasiPeserta(body) {
  const b = body || {};
  const aksi = teksRapi(b.aksi).toLowerCase();
  const oleh = teksRapi(b.oleh).toLowerCase();
  const id_prospek = teksRapi(b.id_prospek).toUpperCase();
  const id_permintaan = teksRapi(b.id_permintaan);
  const catatan = teksRapi(b.catatan);
  const data = {};
  const pesan = [];

  if (!AKSI_PESERTA.includes(aksi)) pesan.push('Aksi harus tambah, ubah, atau arsip.');
  // US-07/FR-15: admin mengelola semua peserta; AE hanya peserta miliknya (diperiksa di prosesPeserta).
  if (!['admin', 'ae_a', 'ae_b'].includes(oleh)) pesan.push('Hanya admin atau AE yang boleh mengelola peserta.');
  if (aksi !== 'tambah' && !/^P\d{2,}$/.test(id_prospek)) pesan.push('id_prospek tidak valid.');
  if (catatan.length > 200) pesan.push('Catatan maksimal 200 karakter.');

  if (aksi === 'tambah') {
    if (!id_permintaan) pesan.push('id_permintaan wajib diisi.');
    for (const k of ['nama_perusahaan', 'sektor', 'nama_pic', 'no_hp_pic', 'kategori']) {
      const [v, galat] = periksaKolomPeserta(k, b[k], oleh);
      data[k] = v;
      if (galat) pesan.push(galat);
    }
    if (b.ae !== undefined && teksRapi(b.ae) !== '') {
      const [v, galat] = periksaKolomPeserta('ae', b.ae, oleh);
      data.ae = v;
      if (galat) pesan.push(galat);
    }
  } else if (aksi === 'ubah') {
    const ada = KOLOM_UBAH_PESERTA.filter((k) => b[k] !== undefined);
    if (!ada.length) pesan.push('Tidak ada kolom yang diubah.');
    for (const k of ada) {
      const [v, galat] = periksaKolomPeserta(k, b[k], oleh);
      data[k] = v;
      if (galat) pesan.push(galat);
    }
  }

  return { valid: pesan.length === 0, pesan: pesan.join(' '), aksi, oleh, id_prospek, id_permintaan, catatan, data };
}

function tolakPeserta(pesan) {
  return { boleh: false, pesan };
}

function idKetemu(daftar, id) {
  return daftar.find((r) => String(r.id_prospek).trim().toUpperCase() === id);
}

// D = Olah Data Sheet (Prospek, Histori); m = validasiPeserta. Hasil: tolak (boleh false), lama, atau body_tulis.
function prosesPeserta(D, m, waktu) {
  const daftar = D.tabel.Prospek.filter((r) => String(r.id_prospek || '').trim() !== '');
  const aktor = AKTOR[m.oleh];
  let nomorH = nomorBerikut(D.tabel.Histori, 'id_histori');
  const histori = (id_prospek, jenis, nilai_lama, nilai_baru, catatan) => ({
    id_histori: idBaru('H', nomorH++), waktu, id_prospek, aktor, jenis, nilai_lama, nilai_baru, catatan,
  });

  if (m.aksi === 'tambah') {
    const tanda = '; ' + tandaPermintaan(m.id_permintaan);
    const lama = D.tabel.Histori.find(
      (r) => String(r.aktor).trim() === aktor && String(r.jenis).trim() === 'pendaftaran' && String(r.catatan || '').endsWith(tanda)
    );
    if (lama) {
      return { lama: true, respons: { status: 'ok', aksi: 'tambah', id_prospek: lama.id_prospek, pesan: `Peserta sudah ditambahkan sebagai ${lama.id_prospek}.`, berulang: true } };
    }
    const kunci = normalisasiKunci(m.data.nama_perusahaan);
    const ada = daftar.find((r) => String(r.kunci_normal || '').trim() === kunci);
    if (ada) return tolakPeserta(`${ada.nama_perusahaan} sudah terdaftar sebagai ${ada.id_prospek}; data tidak ditambah.`);

    const nomorMaks = Math.max(0, ...daftar.map((r) => parseInt(String(r.id_prospek).replace(/\D/g, ''), 10) || 0));
    const jumlah = { 'AE A': 0, 'AE B': 0 };
    for (const r of daftar) if (r.ae in jumlah) jumlah[r.ae] += 1;
    const ae = m.oleh !== 'admin' ? aktor : m.data.ae || (jumlah['AE B'] < jumlah['AE A'] ? 'AE B' : 'AE A');
    const p = {
      id_prospek: 'P' + String(nomorMaks + 1).padStart(2, '0'),
      nama_perusahaan: m.data.nama_perusahaan,
      kunci_normal: kunci,
      sektor: m.data.sektor,
      ae,
      status: 'Baru',
      kebutuhan: '',
      status_kebutuhan: 'Belum terkonfirmasi', // FR-10
      tgl_tindak_lanjut: '',
      pengingat: '',
      dibuat: waktu,
      diubah: waktu,
      nama_pic: m.data.nama_pic,
      no_hp_pic: m.data.no_hp_pic,
      kategori: m.data.kategori,
      sumber: 'admin',
      aktif: 'TRUE',
    };
    const h = histori(p.id_prospek, 'pendaftaran', '', p.nama_perusahaan,
      `Ditambah dari tabel peserta${m.catatan ? '; ' + m.catatan : ''}${tanda}`);
    return {
      boleh: true,
      body_tulis: { requests: [tambahBaris(D, 'Prospek', [p]), tambahBaris(D, 'Histori', [h])] },
      respons: { status: 'ok', aksi: 'tambah', id_prospek: p.id_prospek, pesan: `${p.nama_perusahaan} ditambahkan sebagai ${p.id_prospek}.`, berulang: false },
    };
  }

  const p = idKetemu(daftar, m.id_prospek);
  if (!p) return tolakPeserta(`Prospek ${m.id_prospek} tidak ditemukan.`);
  if (m.oleh !== 'admin' && String(p.ae).trim() !== aktor) {
    return tolakPeserta(`Prospek ${m.id_prospek} milik ${p.ae}; ${aktor} tidak boleh mengubahnya.`);
  }
  if (!pesertaAktif(p)) return tolakPeserta(`Prospek ${m.id_prospek} sudah diarsipkan; data tidak bisa diubah.`);

  if (m.aksi === 'arsip') {
    const h = histori(p.id_prospek, 'arsip_peserta', 'TRUE', 'FALSE', m.catatan || 'Diarsipkan dari tabel peserta; baris tidak dihapus');
    return {
      boleh: true,
      body_tulis: { requests: [...ubahSel(D, 'Prospek', p, { aktif: 'FALSE', diubah: waktu }), tambahBaris(D, 'Histori', [h])] },
      respons: { status: 'ok', aksi: 'arsip', id_prospek: p.id_prospek, pesan: `${p.nama_perusahaan} (${p.id_prospek}) diarsipkan.`, histori: h },
    };
  }

  // ubah: hanya kolom yang nilainya benar-benar berubah; satu baris Histori ubah_peserta per kolom.
  const berubah = Object.entries(m.data).filter(([k, v]) => String(p[k] ?? '').trim() !== v);
  if (!berubah.length) return tolakPeserta('Tidak ada perubahan.');
  const perubahan = Object.fromEntries(berubah);
