  return {
    boleh: true,
    body_tulis: { requests },
    respons: {
      status: 'ok', id_tiket: m.id_tiket, status_tiket: 'Ditangani', id_draf: idDraf,
      pesan: `Draf jawaban ${idDraf} dibuat dan menunggu persetujuan. Tiket ${m.id_tiket} akan selesai otomatis setelah draf terkirim.`,
    },
  };
